import{_ as t}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as r,D as o,o as n,c as d,I as c,w as b,k as l,a as h,R as u,b as y,e as k}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const q=JSON.parse('{"title":"Key 过期、扫描与删除","description":"理解过期、扫描和删除的成本，以明确目标和可观察返回值控制数据清理。","frontmatter":{"title":"Key 过期、扫描与删除","date":"2026-10-06T00:00:00.000Z","category":"Java课程","tags":["Java","Redis","可靠性"],"description":"理解过期、扫描和删除的成本，以明确目标和可观察返回值控制数据清理。"},"headers":[],"relativePath":"courses/java/15-Redis/06-Key过期扫描与删除.md","filePath":"courses/java/15-Redis/06-Key过期扫描与删除.md","lastUpdated":1791253598000}'),m={name:"courses/java/15-Redis/06-Key过期扫描与删除.md"},g=l("h1",{id:"key-过期、扫描与删除",tabindex:"-1"},[h("Key 过期、扫描与删除 "),l("a",{class:"header-anchor",href:"#key-过期、扫描与删除","aria-label":'Permalink to "Key 过期、扫描与删除"'},"​")],-1),E=u(`<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解过期、扫描和删除的成本，以明确目标和可观察返回值控制数据清理。</p><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>本篇采用 Redis 8 稳定主版本的基础语义；官方文档核对日期：2026-10-06，不声明未验证的补丁版本。需要更高小版本的选项单独标明。</p><p>过期用于限制存活期，扫描用于发现名称，删除用于移除对象；三者不是同一个原子清理动作。运行中的写入、重建和迁槽都会改变扫描结果。</p><p>实验只在本机独立可丢弃 Redis 8、数据库 0 中执行。先通过终端运行 <code>redis-cli -h 127.0.0.1 -p 6379</code>，在交互提示符输入 redis 代码块；有 ACL 时使用 <code>--user lab_user --askpass</code>，不在命令中写密码。输出数组的排版因客户端而异。每节独立重建输入，命名空间 <code>lab:{reliability}:</code> 专用于学习；开始和结束只清理本节明确列出的 key，不把通配符传给删除命令。运行前确认没有业务数据，配置与恢复步骤另按注明的受控前提执行。</p><h2 id="常用用法" tabindex="-1">常用用法 <a class="header-anchor" href="#常用用法" aria-label="Permalink to &quot;常用用法&quot;">​</a></h2><h3 id="expire-设置过期与主动采样边界" tabindex="-1"><code>EXPIRE</code>：设置过期与主动采样边界 <a class="header-anchor" href="#expire-设置过期与主动采样边界" aria-label="Permalink to &quot;\`EXPIRE\`：设置过期与主动采样边界&quot;">​</a></h3><p>用于给一个明确的实验 key 设置秒级生存时间。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：只清理本节明确的学习 key。</span></span>
<span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:ttl</span></span>
<span class="line"><span>SET lab:{reliability}:ttl value</span></span>
<span class="line"><span>EXPIRE lab:{reliability}:ttl 60 NX</span></span>
<span class="line"><span>EXPIRE lab:{reliability}:ttl 120 NX</span></span>
<span class="line"><span># 关键变化：第一次增加 TTL，第二次 NX 不覆盖已有 TTL。</span></span>
<span class="line"><span># 输出：0 或 1（清理）、OK、1、0。</span></span></code></pre></div><p>EXPIRE O(1)；NX/XX/GT/LT 条件自 Redis 7.0 提供，NX 不与其他条件组合。零或负超时立即删除。访问时惰性检查过期，后台主动采样过期 key；不是为每个 key 建独立定时器，也不承诺到点立即释放全部内存。普通 SET 覆盖默认清除 TTL；INCR、HSET 这类原地修改保留 key TTL。<a href="https://redis.io/docs/latest/commands/expire/" target="_blank" rel="noreferrer">EXPIRE 官方语义</a>。</p><h3 id="ttl-区分缺失、永久与剩余期限" tabindex="-1"><code>TTL</code>：区分缺失、永久与剩余期限 <a class="header-anchor" href="#ttl-区分缺失、永久与剩余期限" aria-label="Permalink to &quot;\`TTL\`：区分缺失、永久与剩余期限&quot;">​</a></h3><p>用于读取剩余秒数并辨认两个特殊返回值。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:ttl</span></span>
<span class="line"><span>TTL lab:{reliability}:ttl</span></span>
<span class="line"><span>SET lab:{reliability}:ttl value</span></span>
<span class="line"><span>TTL lab:{reliability}:ttl</span></span>
<span class="line"><span>EXPIRE lab:{reliability}:ttl 60</span></span>
<span class="line"><span>TTL lab:{reliability}:ttl</span></span>
<span class="line"><span># 关键变化：key 从缺失变为永久，再变为限时。</span></span>
<span class="line"><span># 输出：清理数、-2、OK、-1、1、0 到 60 内剩余秒数。</span></span></code></pre></div><p>O(1)；-2 表示 key 不存在，-1 表示无 TTL。PTTL 是毫秒精度，不把两个负值当作过期剩余时间。读到 TTL 后 key 仍可能立即过期；不能以先查 TTL 再写构造原子协议。<a href="https://redis.io/docs/latest/commands/ttl/" target="_blank" rel="noreferrer">TTL</a>。</p><h3 id="scan-完整游标扫描与去重" tabindex="-1"><code>SCAN</code>：完整游标扫描与去重 <a class="header-anchor" href="#scan-完整游标扫描与去重" aria-label="Permalink to &quot;\`SCAN\`：完整游标扫描与去重&quot;">​</a></h3><p>用于以游标逐批枚举当前节点上的匹配 key。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>SET lab:{reliability}:scan-a a</span></span>
<span class="line"><span>SET lab:{reliability}:scan-b b</span></span>
<span class="line"><span>SCAN 0 MATCH lab:{reliability}:scan-* COUNT 10</span></span>
<span class="line"><span># 初始：学习命名空间内只有这两个 scan key；其余 key 不匹配。</span></span>
<span class="line"><span># 关键变化：scan-a/scan-b 写入后开始游标遍历。</span></span>
<span class="line"><span># 输出：下一游标与零到多个匹配 key；若游标非 0，继续传回该游标。</span></span></code></pre></div><p>操作流程：逐次使用返回游标，直到返回 0，保存已处理名称或让操作幂等；不能固定只执行这一页。单次一般 O(1)，完整遍历 O(N)，COUNT 是工作量提示而非返回数上限。完整遍历保证一直存在的元素被返回，不返回一直不存在的元素；变化中的元素结果未定义，可能重复，空批次不代表结束。不是快照；Cluster 需按主节点分别遍历，迁槽另处理。<a href="https://redis.io/docs/latest/commands/scan/" target="_blank" rel="noreferrer">SCAN 保证</a>。扫描后删除有竞态：旧 key 可能被重建，必要时结合业务版本验证。</p><h3 id="unlink-逻辑删除与异步回收" tabindex="-1"><code>UNLINK</code>：逻辑删除与异步回收 <a class="header-anchor" href="#unlink-逻辑删除与异步回收" aria-label="Permalink to &quot;\`UNLINK\`：逻辑删除与异步回收&quot;">​</a></h3><p>用于立即移除名称并观察 key 已不可访问。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>SET lab:{reliability}:unlink value</span></span>
<span class="line"><span># 边界：UNLINK 仅用于可丢弃 lab 单键，生产先核验目标与异步回收压力。</span></span>
<span class="line"><span>UNLINK lab:{reliability}:unlink</span></span>
<span class="line"><span>EXISTS lab:{reliability}:unlink</span></span>
<span class="line"><span># 初始：本段创建一个独立 String 实验 key。</span></span>
<span class="line"><span># 关键变化：unlink 名称从键空间移除，释放工作可交给后台。</span></span>
<span class="line"><span># 输出：OK、1、0。</span></span></code></pre></div><p>危险边界：只删除这个可丢弃学习 key，生产先核验目标。每 key 从键空间摘除 O(1)，后台释放 O(对象分配数量)；简单对象可直接释放，不保证所有类型一定排队。命令返回不等于 RSS 立即下降，分配器可能保留页，异步队列仍占内存。<a href="https://redis.io/docs/latest/commands/unlink/" target="_blank" rel="noreferrer">UNLINK</a>。</p><h3 id="memory-usage-大-key-删除前量化容量" tabindex="-1"><code>MEMORY USAGE</code>：大 Key 删除前量化容量 <a class="header-anchor" href="#memory-usage-大-key-删除前量化容量" aria-label="Permalink to &quot;\`MEMORY USAGE\`：大 Key 删除前量化容量&quot;">​</a></h3><p>用于估算一个明确 key 的内存并选择删除节奏。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:big</span></span>
<span class="line"><span>HSET lab:{reliability}:big a one b two</span></span>
<span class="line"><span># 边界：MEMORY 仅在受控范围采样明确 lab key，避免全量诊断阻塞。</span></span>
<span class="line"><span>MEMORY USAGE lab:{reliability}:big SAMPLES 5</span></span>
<span class="line"><span># 边界：UNLINK 仅用于可丢弃 lab 单键，生产先核验目标与异步回收压力。</span></span>
<span class="line"><span>UNLINK lab:{reliability}:big</span></span>
<span class="line"><span>EXISTS lab:{reliability}:big</span></span>
<span class="line"><span># 初始：big 是可丢弃的小 Hash，用它模拟容量诊断输入。</span></span>
<span class="line"><span># 关键变化：建立 Hash，测量后解除名称绑定。</span></span>
<span class="line"><span># 输出：清理数、2、版本相关字节数、1、0。</span></span></code></pre></div><p>危险：此示例只删除明确学习 key；生产大 Key 删除先测类型、字段/成员数量和字节数，在低峰限制批次与速率，监控延迟、used_memory、RSS、lazyfree_pending_objects，确认业务可重建。MEMORY USAGE 的复杂度取决于采样量；SAMPLES 0 全量采样可能昂贵。UNLINK 不能消除瞬间大量删除产生的后台积压。避免在 Lua 中循环删除海量元素。<a href="https://redis.io/docs/latest/commands/memory-usage/" target="_blank" rel="noreferrer">MEMORY USAGE</a>。</p><h3 id="keys-只在小型可丢弃库演示阻塞枚举" tabindex="-1"><code>KEYS</code>：只在小型可丢弃库演示阻塞枚举 <a class="header-anchor" href="#keys-只在小型可丢弃库演示阻塞枚举" aria-label="Permalink to &quot;\`KEYS\`：只在小型可丢弃库演示阻塞枚举&quot;">​</a></h3><p>用于在确认规模很小的实验库观察全量匹配结果。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 危险：KEYS 阻塞遍历整个数据库；只用于本机小型可丢弃实验库。</span></span>
<span class="line"><span>SET lab:{reliability}:keys-demo one</span></span>
<span class="line"><span># 边界：KEYS 仅用于受控测试环境小库，生产遍历会阻塞服务。</span></span>
<span class="line"><span>KEYS lab:{reliability}:keys-*</span></span>
<span class="line"><span># 初始：该前缀下没有其他学习 key。</span></span>
<span class="line"><span># 关键变化：keys-demo 增加后全量枚举匹配名称。</span></span>
<span class="line"><span># 输出：OK、包含 lab:{reliability}:keys-demo 的数组。</span></span></code></pre></div><p>O(N)，即使匹配前缀很窄也遍历库；生产枚举优先 SCAN，别把 KEYS * 放进接口或运维定时任务。<a href="https://redis.io/docs/latest/commands/keys/" target="_blank" rel="noreferrer">KEYS</a>。</p><h3 id="del-明确名称删除与-broad-del-风险" tabindex="-1"><code>DEL</code>：明确名称删除与 broad DEL 风险 <a class="header-anchor" href="#del-明确名称删除与-broad-del-风险" aria-label="Permalink to &quot;\`DEL\`：明确名称删除与 broad DEL 风险&quot;">​</a></h3><p>用于删除两个已核验的实验名称并观察实际删除数。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 危险：DEL 只针对这两个可丢弃学习 key，禁止扫描业务库后无审查批量删除。</span></span>
<span class="line"><span>SET lab:{reliability}:del-a a</span></span>
<span class="line"><span>SET lab:{reliability}:del-b b</span></span>
<span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:del-a lab:{reliability}:del-b</span></span>
<span class="line"><span>EXISTS lab:{reliability}:del-a lab:{reliability}:del-b</span></span>
<span class="line"><span># 初始：两个独立学习 String 创建后各保存一个值。</span></span>
<span class="line"><span># 关键变化：del-a/del-b 两个名称与其对象同步删除。</span></span>
<span class="line"><span># 输出：OK、OK、2、0。</span></span></code></pre></div><p>DEL 接收具体名称，不展开 *；O(key 数)，复杂集合还需 O(元素数)释放。大对象同步释放可能造成长尾延迟，多 key 在 Cluster 必须同槽。broad DEL 的危险常来自脚本把大量匹配结果变成删除列表；需预览、审批范围和备份，分批删除也不能解决误删。<a href="https://redis.io/docs/latest/commands/del/" target="_blank" rel="noreferrer">DEL</a>。</p><h3 id="flushdb-数据库级删除的隔离演示" tabindex="-1"><code>FLUSHDB</code>：数据库级删除的隔离演示 <a class="header-anchor" href="#flushdb-数据库级删除的隔离演示" aria-label="Permalink to &quot;\`FLUSHDB\`：数据库级删除的隔离演示&quot;">​</a></h3><p>用于在单独可丢弃实例中验证整个当前数据库被清空。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 危险：只在无业务数据的独立本机可丢弃实例执行；不得连接生产。</span></span>
<span class="line"><span>SET lab:{reliability}:flush one</span></span>
<span class="line"><span># 边界：FLUSHDB 仅用于独立测试环境，生产执行将删除整个当前库。</span></span>
<span class="line"><span>FLUSHDB SYNC</span></span>
<span class="line"><span>DBSIZE</span></span>
<span class="line"><span># 初始：当前数据库只含刚创建的学习 key，其他实验已清理。</span></span>
<span class="line"><span># 关键变化：数据库中的所有 key 被删除。</span></span>
<span class="line"><span># 输出：OK、OK、0。</span></span></code></pre></div><p>FLUSHDB 清空当前库，FLUSHALL 清空所有库；两者都没有业务前缀边界。ASYNC 只异步释放，不是安全删除或撤销功能；Cluster 的库与节点作用域还需确认。生产误操作没有命令级回滚，只能走事先演练的备份恢复。<a href="https://redis.io/docs/latest/commands/flushdb/" target="_blank" rel="noreferrer">FLUSHDB</a>。</p><h2 id="易混点" tabindex="-1">易混点 <a class="header-anchor" href="#易混点" aria-label="Permalink to &quot;易混点&quot;">​</a></h2><p>TTL 到期与物理回收存在时间差；SCAN 返回游标是继续令牌，不能当作偏移页码。</p><h2 id="课后小问" tabindex="-1">课后小问 <a class="header-anchor" href="#课后小问" aria-label="Permalink to &quot;课后小问&quot;">​</a></h2><ol><li>SCAN 返回空数组时应否停止？</li></ol><p>答案：只看返回游标，非 0 就继续；遍历期间重复返回需去重或幂等。</p><ol start="2"><li>怎样处理写命令响应丢失？</li></ol><p>答案：响应丢失不能证明没有执行；先检查业务状态，对非幂等写入使用业务 ID、去重记录或有界恢复流程。</p><h2 id="本节小结" tabindex="-1">本节小结 <a class="header-anchor" href="#本节小结" aria-label="Permalink to &quot;本节小结&quot;">​</a></h2><p>先界定 key 和容量，再选择有界扫描与删除，观察逻辑消失和内存回收两个阶段。</p><h2 id="快速回顾" tabindex="-1">快速回顾 <a class="header-anchor" href="#快速回顾" aria-label="Permalink to &quot;快速回顾&quot;">​</a></h2><p>按 H3 定位真实命令或操作流程，重建初始状态并读回结果，再检查超时、容量和数据安全边界。</p>`,50);function S(a,T,_,L,v,f){const p=t,i=o("ClientOnly");return n(),d("div",null,[g,c(i,null,{default:b(()=>{var s,e;return[(((s=a.$frontmatter)==null?void 0:s.aside)??!0)&&(((e=a.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(n(),y(p,{key:0,article:a.$frontmatter},null,8,["article"])):k("",!0)]}),_:1}),E])}const P=r(m,[["render",S]]);export{q as __pageData,P as default};
